text:
{
  "design": {
    "theme": "crayon",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall equal sharing", "look_at": {"kind": "picture", "shows": "Two plates with the same number of apples"}, "teaches": []},
    {"slide": 2, "does": "Introduce the learning goals", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Model halves and quarters of shapes", "look_at": {"kind": "diagram", "shows": "One shaded part out of two or four equal parts"}, "teaches": [1]},
    {"slide": 4, "does": "Identify fractions of similar shapes", "look_at": {"kind": "diagram", "shows": "Two shapes with one equal part shaded"}, "teaches": [1]},
    {"slide": 5, "does": "Correct the unequal-parts misconception", "look_at": {"kind": "diagram", "shows": "Equal halves beside two unequal pieces"}, "teaches": [1]},
    {"slide": 6, "does": "Model finding half of an amount", "look_at": {"kind": "diagram", "shows": "Twelve counters shared into two equal groups"}, "teaches": [2]},
    {"slide": 7, "does": "Find half by equal sharing", "look_at": {"kind": "picture", "shows": "Sixteen counters ready to share"}, "teaches": [2]},
    {"slide": 8, "does": "Model finding a quarter of an amount", "look_at": {"kind": "diagram", "shows": "Twelve counters shared into four equal groups"}, "teaches": [3]},
    {"slide": 9, "does": "Find a quarter by equal sharing", "look_at": {"kind": "picture", "shows": "Sixteen counters ready to share"}, "teaches": [3]},
    {"slide": 10, "does": "Check the meaning of one quarter", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 11, "does": "Practise sharing different amounts", "look_at": {"kind": "none", "shows": null}, "teaches": [2, 3]},
    {"slide": 12, "does": "Apply fractions to a new sharing problem", "look_at": {"kind": "picture", "shows": "Twenty strawberries available for sharing"}, "teaches": [2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Halves and quarters",
    "lead": "Look at the plates. Is this fair sharing?",
    "picture": {
      "shows": "two plates, each holding three apples",
      "must_see": ["two matching plates", "three apples each"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Equal parts",
      "lead": "Equal parts are the same size.",
      "points": [
        "One half is one of two equal parts.",
        "One quarter is one of four equal parts."
      ],
      "figure": {
        "kind": "fraction-shapes",
        "shows": "a rectangle showing one half and a square showing one quarter",
        "alt": "A rectangle has one of two equal parts shaded. A square has one of four equal parts shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 2, "cut": "vertical", "shaded": 1, "name": "½"},
          {"shape": "square", "parts": 4, "cut": "grid", "shaded": 1, "name": "¼"}
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Name the shaded part",
      "lead": "Name the fraction in A and B. Explain how you know.",
      "figure": {
        "kind": "fraction-shapes",
        "shows": "two shapes for pupils to identify the shaded fraction",
        "alt": "Shape A has two equal parts with one shaded. Shape B has four equal parts with one shaded.",
        "title": null,
        "shapes": [
          {"shape": "rectangle", "parts": 2, "cut": "horizontal", "shaded": 1, "name": "A"},
          {"shape": "square", "parts": 4, "cut": "vertical", "shaded": 1, "name": "B"}
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Two pieces are not always halves",
      "lead": "Half means two equal parts, not just two pieces.",
      "points": [
        "A shows halves: both parts are equal.",
        "B does not: the parts are unequal."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "two identical rectangles side by side: A split vertically into two equal pieces with the left piece shaded; B split vertically into a narrow left piece and a wide right piece with the left piece shaded",
        "labels": ["A", "B"]
      }
    },
    {
      "template": "visual-text",
      "heading": "Find half of 12",
      "lead": "Share 12 counters into two equal groups.",
      "points": [
        "Count one group: it has 6 counters.",
        "Half of 12 is 6."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "twelve counters shared equally into two groups of six",
        "alt": "Twelve counters are shared into two rings, with six counters in each ring.",
        "title": null,
        "total": 12,
        "groups": 2,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find half of 16",
      "questions": [
        "Draw two groups. Share the 16 counters equally.",
        "How many counters are in one group?",
        "Complete: Half of 16 is __."
      ],
      "instruction": "Draw and write on your worksheet.",
      "picture": {
        "shows": "sixteen separate counters in one ungrouped collection",
        "must_see": ["sixteen round counters", "one loose collection"],
        "subject": "generic"
      }
    },
    {
      "template": "visual-text",
      "heading": "Find a quarter of 12",
      "lead": "Share 12 counters into four equal groups.",
      "points": [
        "Count one group: it has 3 counters.",
        "One quarter of 12 is 3."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "twelve counters shared equally into four groups of three",
        "alt": "Twelve counters are shared into four rings, with three counters in each ring.",
        "title": null,
        "total": 12,
        "groups": 4,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find a quarter of 16",
      "questions": [
        "Draw four groups. Share the 16 counters equally.",
        "How many counters are in one group?",
        "Complete: One quarter of 16 is __."
      ],
      "instruction": "Draw and write on your worksheet.",
      "picture": {
        "shows": "sixteen separate counters in one ungrouped collection",
        "must_see": ["sixteen round counters", "one loose collection"],
        "subject": "generic"
      }
    },
    {
      "template": "hinge",
      "heading": "Choose one answer",
      "stem": "What is one quarter of 8 counters?",
      "options": ["2 counters", "4 counters", "8 counters"],
      "correct": 1
    },
    {
      "template": "practice",
      "heading": "Share equally",
      "questions": [
        "Find half of 10 counters.",
        "Find one quarter of 4 counters.",
        "Find one quarter of 20 counters."
      ],
      "instruction": "Draw equal groups. Write each answer.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Strawberries for a picnic",
      "questions": [
        "Share 20 strawberries equally between 2 children. How many each?",
        "Share 20 strawberries equally between 4 children. How many each?",
        "Stretch: Which share is bigger? Explain why."
      ],
      "instruction": "Draw each way of sharing. Write your answers.",
      "picture": {
        "shows": "twenty strawberries in one loose collection",
        "must_see": ["twenty red strawberries", "one loose collection"],
        "subject": "generic"
      }
    }
  ]
}
